			bufApp(&buf, s, w, char)
			w++
			r++

			for r < n && s[r] == char {
				r++
			}
		} else {

			bufApp(&buf, s, w, s[r])
			w++
			r++
		}
	}

	if len(buf) == 0 {
		return s[:w]
	}
	return string(buf[:w])
}
