		case *ast.StarExpr:
			a.checkDeref(t.X, env, "pointer dereference")
		case *ast.SelectorExpr:
			switch {
			case isPointerType(a.exprType(t.X)):
				a.checkDeref(t.X, env, "pointer dereference")
			case isInterfaceType(a.exprType(t.X)):
				a.checkDeref(t.X, env, "interface method invocation")
			}
